CREATE OR REPLACE FUNCTION audit_log_append_only() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF TG_OP = 'DELETE' AND OLD.created_at < now() - INTERVAL '365 days'
     AND coalesce(current_setting('sysarch.audit_archive', true), '') = 'on' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'audit_log is append-only (P2 §7.2): % refused', TG_OP USING ERRCODE = 'insufficient_privilege';
END
$fn$
